package com.loanops.fincompass;
import com.github.tomakehurst.wiremock.WireMockServer;import com.loanops.api.ApiNotFoundException;import com.loanops.fincompass.matching.*;import com.loanops.fincompass.simulation.*;import com.loanops.fincompass.twin.*;import com.loanops.normalization.SourceNormalizationService;import com.loanops.publication.PublicationService;import com.loanops.source.domain.DataSourceCode;import com.loanops.source.service.SourceIngestionService;import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.io.ClassPathResource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import org.testcontainers.utility.DockerImageName;
import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.util.*;
import static com.github.tomakehurst.wiremock.client.WireMock.*;import static com.loanops.fincompass.matching.MatchingModels.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("fincompass-demo")
class MatchingIntegrationTest {
 static final WireMockServer WIRE=new WireMockServer(com.github.tomakehurst.wiremock.core.WireMockConfiguration.wireMockConfig().dynamicPort());static{WIRE.start();}
 @AfterAll static void stop(){WIRE.stop();}
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres:17.11-alpine"));
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::getJdbcUrl);r.add("spring.datasource.username",DB::getUsername);r.add("spring.datasource.password",DB::getPassword);r.add("fincompass.open-banking.encryption-key",()->Base64.getEncoder().encodeToString(new byte[32]));r.add("loanops.sources.fss-finlife.base-url",WIRE::baseUrl);r.add("loanops.sources.fss-finlife.path",()->"/fss");r.add("loanops.sources.fss-finlife.api-key",()->"test-api-key");}
 @Autowired SourceIngestionService ingestion;@Autowired SourceNormalizationService normalization;@Autowired PublicationService publication;@Autowired ProductCatalogReader catalog;@Autowired MatchService matches;@Autowired FinancialTwinStore twins;@Autowired ScenarioService scenarios;@Autowired JdbcTemplate jdbc;@Autowired MockMvc http;@Autowired ObjectMapper json;
 static final String OWNER="golden-homebuyer";
 @BeforeEach void products()throws Exception{if(jdbc.queryForObject("SELECT count(*) FROM loanops.serving_product_terms",Integer.class)>0)return;WIRE.resetAll();WIRE.stubFor(get(urlPathEqualTo("/fss")).willReturn(aResponse().withStatus(200).withHeader("Content-Type","application/json").withBody(new ClassPathResource("fixtures/fss/mortgage-loans.json").getContentAsString(StandardCharsets.UTF_8).replace("\"lend_rate_avg\": \"4.97\"","\"lend_rate_avg\": \"5.97\""))));long id=ingestion.ingest(DataSourceCode.FSS_FINLIFE).sourceRunId();normalization.normalize(id);publication.publish(id);}
 @Test void servingProductsBecomeFrozenInsufficientCandidatesWithoutInventedEligibility(){var run=match();assertThat(run.candidates()).hasSize(2).allSatisfy(c->{assertThat(c.status()).isEqualTo(Status.INSUFFICIENT_DATA);assertThat(c.score()).isNull();assertThat(c.rank()).isNull();assertThat(c.product().loanProductId()).isPositive();assertThat(c.product().productTermId()).isPositive();assertThat(c.product().productRawHash()).hasSize(64);assertThat(c.product().termRawHash()).hasSize(64);assertThat(c.product().sourceType()).isEqualTo("REAL_PRODUCT_DATA");assertThat(c.limitations()).contains("AMOUNT_RANGE_MISSING","TERM_RANGE_MISSING","EXACT_REPAYMENT_MAPPING_MISSING","ELIGIBILITY_MISSING");});assertThat(run.scoreRuleVersion()).isEqualTo(MatchingEngine.SCORE_RULE_VERSION);}
 @Test void runRoundTripsEncryptedAndImmutable(){var run=match();assertThat(matches.get(OWNER,run.matchRunId())).isEqualTo(run);String payload=jdbc.queryForObject("SELECT payload_ciphertext FROM loanops.product_match_payload WHERE match_run_id=?",String.class,run.matchRunId());assertThat(payload).doesNotContain("우리아파트론","590000000","minimumRate");assertThatThrownBy(()->jdbc.update("DELETE FROM loanops.product_match_candidate WHERE match_run_id=?",run.matchRunId())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void laterServingUpdateCannotChangeOldRun()throws Exception{var old=match();var before=matches.get(OWNER,old.matchRunId());WIRE.resetAll();String body=new ClassPathResource("fixtures/fss/mortgage-loans.json").getContentAsString(StandardCharsets.UTF_8).replace("\"lend_rate_min\": \"3.96\"","\"lend_rate_min\": \"4.36\"").replace("\"lend_rate_avg\": \"4.97\"","\"lend_rate_avg\": \"5.97\"");WIRE.stubFor(get(urlPathEqualTo("/fss")).willReturn(aResponse().withStatus(200).withHeader("Content-Type","application/json").withBody(body)));long id=ingestion.ingest(DataSourceCode.FSS_FINLIFE).sourceRunId();normalization.normalize(id);publication.publish(id);var newer=match();assertThat(matches.get(OWNER,old.matchRunId())).isEqualTo(before);assertThat(newer.candidates().stream().map(c->c.product().productTermId()).toList()).isNotEqualTo(before.candidates().stream().map(c->c.product().productTermId()).toList());}
 @Test void apiAndOwnershipBoundariesAreEnforced()throws Exception{var home=home();var request=new MatchRecords.MatchRequest(home.scenarioId(),null,new BigDecimal("4000000"),null,List.of("AMORTIZING"),5);String response=http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/loan-product-matches").contentType("application/json").content(json.writeValueAsString(request))).andExpect(status().isOk()).andExpect(jsonPath("$.candidates").isArray()).andExpect(jsonPath("$.scoreRuleVersion").value(MatchingEngine.SCORE_RULE_VERSION)).andReturn().getResponse().getContentAsString();String id=json.readTree(response).get("matchRunId").asText();http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/loan-product-matches/"+id)).andExpect(status().isOk());assertThatThrownBy(()->matches.get("another-owner",UUID.fromString(id))).isInstanceOf(ApiNotFoundException.class);http.perform(options("/api/v1/loan-product-matches").header("Origin","http://localhost:5173").header("Access-Control-Request-Method","POST").header("Access-Control-Request-Headers","content-type")).andExpect(status().isOk());}
 @Test void directRequestUsesLatestTwinButDoesNotInventPostPurchaseStress(){var run=matches.match(OWNER,new MatchRecords.MatchRequest(null,new BigDecimal("300000000"),new BigDecimal("3000000"),30,List.of("AMORTIZING"),3));assertThat(run.scenarioId()).isNull();assertThat(run.financialSnapshotId()).isEqualTo(twins.latest(OWNER).financialSnapshotId());assertThat(run.candidates()).allSatisfy(c->assertThat(c.limitations()).contains("POST_SCENARIO_METRICS_REQUIRE_HOME_SCENARIO"));}
 private MatchRecords.Run match(){var home=home();return matches.match(OWNER,new MatchRecords.MatchRequest(home.scenarioId(),null,new BigDecimal("4000000"),null,List.of("AMORTIZING"),5));}
 private ScenarioRecords.Scenario home(){return scenarios.createHome(OWNER,ScenarioExamples.golden(twins.latest(OWNER).financialSnapshotId()));}
}
